const http = require('http');
const fs = require('fs');
const path = require('path');

const url = process.env.STATUS_URL || 'http://127.0.0.1:65165/status';

http.get(url, (res) => {
  let body = '';
  res.on('data', (chunk) => { body += chunk; });
  res.on('end', () => {
    let status = res.statusCode;
    if (body) {
      try {
        const parsed = JSON.parse(body);
        if (parsed && parsed.status !== undefined) status = parsed.status;
      } catch (e) {
        const m = body.match(/"status"\s*:\s*(\d+)/);
        if (m) status = Number(m[1]);
      }
    }
    const dir = path.join(__dirname, 'results');
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'status.json'), JSON.stringify({ status }, null, 2) + '\n');
    console.log('status=' + status);
  });
}).on('error', (err) => {
  console.error('request failed:', err.message);
  process.exit(1);
});

